using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options that use the default reflection-based resolver ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"  Serialized: {json}");

Person? roundTripped = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"  Deserialized: {roundTripped}");

// 2) TryGetTypeInfo<T>() — probe without throwing
//    Person is resolvable (reflection resolver handles any type)
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"\nTryGetTypeInfo<Person> → found ({info!.Type.Name})");
else
    Console.WriteLine("\nTryGetTypeInfo<Person> → not available");

// Now use a source-gen context that only knows about Person.
// Asking for List<int> will fail — but TryGetTypeInfo won't throw.
var sgOptions = new JsonSerializerOptions { TypeInfoResolver = PersonContext.Default };

if (sgOptions.TryGetTypeInfo<List<int>>(out JsonTypeInfo<List<int>>? listInfo))
    Console.WriteLine($"TryGetTypeInfo<List<int>> → found ({listInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<List<int>> → not available (expected)");

// ----- Types -----
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;

